[
  {
    "name": "林舟",
    "description": "前水利工程师，团队领航者，背负着寻找水源的使命与失去女儿的伤痛",
    "appearance": "38岁亚洲男性，瘦削坚毅，颧骨突出，鬓角短发泛灰",
    "costume": "磨损的深灰色防辐射长风衣，内搭土黄色工装背心，护目镜推在额上",
    "personality": "沉默寡言、极度理性、外冷内热"
  },
  {
    "name": "阿娜",
    "description": "团队中的年轻医者，敏锐而善良，是小队的人性之光",
    "appearance": "26岁中亚混血女性，黑色短卷发，深棕色眼睛，左眉有细小疤痕",
    "costume": "褪色橄榄绿医用夹克，背着旧皮药箱",
    "personality": "坚韧、温柔、信仰希望"
  },
  {
    "name": "老郑",
    "description": "退伍军人，团队的火力担当，但对水源真相有所隐瞒",
    "appearance": "52岁东亚男性，方脸络腮胡，右眼斜疤",
    "costume": "锈红色旧军用背心，左臂金属义肢",
    "personality": "暴躁、忠诚、藏着秘密"
  },
  {
    "name": "小豆",
    "description": "13岁的孤儿，团队的希望象征",
    "appearance": "瘦小少年，乱蓬蓬的黑发，大眼睛",
    "costume": "过大的灰色连帽衫，腰间系着旧皮带",
    "personality": "机警、早熟、渴望被保护"
  }
]

[
  {
    "name": "辐射荒原",
    "description": "小队跋涉的主战场，漫天黄沙、扭曲金属残骸、远处蘑菇云的阴影",
    "visualStyle": "暖黄主调夹杂冷蓝辐射光晕，低对比度，长镜头展现荒凉"
  },
  {
    "name": "废弃公路",
    "description": "龟裂的高速公路，地平线延伸到尽头",
    "visualStyle": "高反差正午光，路面反光强烈，远处热浪扭曲"
  },
  {
    "name": "干涸河床",
    "description": "小队以为找到水源却扑空的地点",
    "visualStyle": "阴沉天空，蓝灰色调，河床布满龟裂纹"
  },
  {
    "name": "废弃加油站",
    "description": "避难所，藏着老郑的秘密线索",
    "visualStyle": "昏黄室内灯光，灰尘漂浮，逆光剪影"
  }
]
